const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const somalia = ee.FeatureCollection('FAO/GAUL/2015/level0')
    .filter(ee.Filter.eq('ADM0_NAME', 'Somalia'));

  // Define the common analysis period (March 1 to September 30)
  const startMonth = 3;
  const endMonth = 9;

  // Define the target year and historical range
  const targetYear = 2022;
  const historicalStartYear = 1981;
  const historicalEndYear = 2021;

  // Define the scale for reduceRegion to avoid memory errors and speed up
  const scale = 5000; // CHIRPS original resolution is ~5.5km, so 5km is appropriate.

  // 2. Data Acquisition & Check
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');

  // Helper function to get precipitation for a given year range and period
  const getPrecipitationSum = (year, startMonth, endMonth, geometry) => {
    const startDate = ee.Date.fromYMD(year, startMonth, 1);
    const endDate = ee.Date.fromYMD(year, endMonth, 1).advance(1, 'month').advance(-1, 'day'); // Last day of endMonth

    let collection = chirps.filterDate(startDate, endDate)
      .filterBounds(geometry);

    if (collection.size().getInfo() === 0) {
      return null; // Indicates no images for this period
    }

    // Sum precipitation for the period
    const precipSum = collection.sum();

    // Calculate valid pixels
    const pixelCount = precipSum.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('precipitation');

    if (pixelCount.getInfo() === 0) {
      return 0; // Images exist but no valid pixels after reduction
    }

    const value = precipSum.reduceRegion({
      reducer: ee.Reducer.mean(), // Mean precipitation over the region
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('precipitation');

    return value.getInfo();
  };

  // --- Calculate 2022 Precipitation ---
  const precip2022 = getPrecipitationSum(targetYear, startMonth, endMonth, somalia);
  console.log(`2022 (Mar-Sep) Precipitation: ${precip2022 !== null ? precip2022.toFixed(2) + ' mm' : 'N/A'}`);

  if (precip2022 === null) {
    console.log("C1: No CHIRPS data found for Somalia in March-September 2022.");
    return;
  }
  if (precip2022 === 0) {
    console.log("C2: No valid pixels for Somalia in March-September 2022 after processing.");
    return;
  }
  if (precip2022 === undefined || isNaN(precip2022)) {
    console.log("C3: Calculation failure for 2022 precipitation.");
    return;
  }

  // --- Calculate Historical Average Precipitation ---
  let annualPrecips = [];
  for (let year = historicalStartYear; year <= historicalEndYear; year++) {
    const precip = getPrecipitationSum(year, startMonth, endMonth, somalia);
    if (precip !== null) { // Only include years with data
      annualPrecips.push(precip);
    }
  }

  console.log(`Historical years with data: ${annualPrecips.length} out of ${historicalEndYear - historicalStartYear + 1}`);

  if (annualPrecips.length === 0) {
    console.log("C1: No CHIRPS data found for Somalia in any historical March-September period (1981-2021).");
    return;
  }

  const historicalAveragePrecip = annualPrecips.reduce((a, b) => a + b, 0) / annualPrecips.length;
  console.log(`1981-2021 (Mar-Sep) Average Precipitation: ${historicalAveragePrecip.toFixed(2)} mm`);

  if (historicalAveragePrecip === undefined || isNaN(historicalAveragePrecip)) {
    console.log("C3: Calculation failure for historical average precipitation.");
    return;
  }

  // 5. Validation & Final Answer
  const decrease = precip2022 < historicalAveragePrecip;

  if (decrease) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
